const WCC_STYLES=`:host{display:block;width:100%;color:#fff}ha-card{overflow:hidden;border:0;background:transparent;box-shadow:none}.shell{min-height:720px;box-sizing:border-box;padding:28px;border-radius:28px;position:relative;overflow:hidden;background:linear-gradient(145deg,#16283d,#315b7d);font-family:Roboto,sans-serif}.shell::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 80% 10%,rgba(255,255,255,.2),transparent 32%),linear-gradient(135deg,rgba(255,255,255,.06),transparent 45%);pointer-events:none}.shell.sun{background:linear-gradient(145deg,#087db8,#54b6df)}.shell.cloud{background:linear-gradient(145deg,#354b62,#70869b)}.shell.rain{background:linear-gradient(145deg,#152f48,#406783)}.shell.storm{background:linear-gradient(145deg,#171a2e,#3d4264)}.shell.snow{background:linear-gradient(145deg,#50758e,#a5c4d2)}.shell.night{background:linear-gradient(145deg,#080f25,#263b62)}.topbar,.hero,.metrics,section,.footer{position:relative;z-index:1}.topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.eyebrow,.section-title{font-size:11px;letter-spacing:.18em;opacity:.72;font-weight:700}.title{font-size:28px;font-weight:700;margin-top:4px}.condition-pill{padding:9px 14px;border:1px solid rgba(255,255,255,.22);background:rgba(0,0,0,.12);border-radius:999px;backdrop-filter:blur(12px);white-space:nowrap}.hero{display:flex;align-items:end;justify-content:space-between;gap:20px;min-height:260px;padding:20px 8px 30px}.hero-main{display:flex;align-items:center;gap:24px}.hero-icon{font-size:92px;line-height:1;filter:drop-shadow(0 8px 18px rgba(0,0,0,.16))}.temperature{font-size:96px;line-height:.95;font-weight:300;letter-spacing:-.06em}.temperature span{font-size:36px;vertical-align:top;margin-left:6px;opacity:.75}.feels{margin-top:10px;opacity:.72;font-size:15px}.location{align-self:end;opacity:.72;font-size:14px}.metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:30px}.metric{padding:17px;border-radius:18px;background:rgba(0,0,0,.14);border:1px solid rgba(255,255,255,.1);backdrop-filter:blur(12px)}.metric span{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.12em;opacity:.62;margin-bottom:7px}.metric strong{font-size:18px;font-weight:600}.section-title{margin:0 0 12px 3px}.days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}.day{text-align:center;padding:16px 8px;min-height:150px;border-radius:18px;background:rgba(0,0,0,.13);border:1px solid rgba(255,255,255,.09);backdrop-filter:blur(10px)}.day-name{font-size:12px;font-weight:700;opacity:.75}.day-icon{font-size:32px;margin:13px 0}.day-temp{font-size:15px}.day-temp span{opacity:.55;margin-left:4px}.day-rain{margin-top:10px;font-size:11px;opacity:.62}.empty{padding:30px;opacity:.6}.footer{margin-top:18px;text-align:right;font-size:11px;opacity:.48}@media(max-width:900px){.metrics{grid-template-columns:repeat(3,1fr)}.days{grid-template-columns:repeat(4,1fr)}.hero{min-height:220px}.temperature{font-size:72px}.hero-icon{font-size:70px}}@media(max-width:600px){.shell{padding:18px;border-radius:20px;min-height:0}.topbar{flex-direction:column}.condition-pill{align-self:flex-start}.hero{min-height:180px;padding:10px 0 20px;align-items:flex-start;flex-direction:column}.hero-main{gap:15px}.hero-icon{font-size:60px}.temperature{font-size:64px}.location{align-self:flex-start}.metrics{grid-template-columns:repeat(2,1fr)}.days{grid-template-columns:repeat(2,1fr)}}`;
class WeatherCommandCenter extends HTMLElement{
 static getStubConfig(){return{type:'custom:weather-command-center',weather_entity:'weather.home',name:'Home Weather'}}
 setConfig(c){if(!c||typeof c!=='object')throw new Error('Invalid configuration');this.config={weather_entity:c.weather_entity||c.entity||'weather.home',name:c.name||'Weather',temperature_entity:c.temperature_entity,humidity_entity:c.humidity_entity,pressure_entity:c.pressure_entity,wind_speed_entity:c.wind_speed_entity,wind_direction_entity:c.wind_direction_entity,uv_entity:c.uv_entity,location:c.location||'',forecast_days:Math.min(7,Math.max(1,Number(c.forecast_days||7)))};this._forecastKey='';this._forecast=[];this.render()}
 set hass(h){this._hass=h;this.render()} getCardSize(){return 8}
 _state(id){return id&&this._hass?this._hass.states[id]:undefined}_value(id,f='—'){const s=this._state(id);return s&&!['unavailable','unknown'].includes(s.state)?s.state:f}_unit(id,f=''){return this._state(id)?.attributes?.unit_of_measurement||f}
 _icon(c){const m={sunny:'☀️','clear-night':'🌙',partlycloudy:'⛅',cloudy:'☁️',rainy:'🌧️',pouring:'🌧️',lightning:'⛈️','lightning-rainy':'⛈️',snowy:'🌨️',snow:'❄️',windy:'💨','windy-variant':'🌬️',fog:'🌫️',hail:'🌨️',exceptional:'⚠️'};return m[c]||'🌤️'}
 _label(c){return c?c.replace(/-/g,' ').replace(/\b\w/g,x=>x.toUpperCase()):'Unknown'}_bg(c){if(!c)return'default';if(c.includes('lightning'))return'storm';if(c.includes('rain'))return'rain';if(c.includes('snow'))return'snow';if(c==='cloudy'||c==='fog')return'cloud';if(c==='clear-night')return'night';if(c==='sunny'||c==='partlycloudy')return'sun';return'default'}
 async _getForecast(){if(!this._hass?.callWS)return[];try{const r=await this._hass.callWS({type:'call_service',domain:'weather',service:'get_forecasts',service_data:{type:'daily'},target:{entity_id:this.config.weather_entity},return_response:true});return r?.response?.[this.config.weather_entity]?.forecast||r?.[this.config.weather_entity]?.forecast||[]}catch(e){console.warn('Weather Command Center forecast error',e);return[]}}
 _day(d){try{return new Intl.DateTimeFormat(undefined,{weekday:'short'}).format(new Date(d))}catch(e){return'—'}}_time(d){try{return new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit'}).format(new Date(d))}catch(e){return'—'}}
 async render(){if(!this.config||!this._hass)return;const w=this._state(this.config.weather_entity);if(!w){this.innerHTML=`<ha-card><div style="padding:20px">Weather entity <b>${this.config.weather_entity}</b> was not found.</div></ha-card>`;return}if(!this._styleAdded){const s=document.createElement('style');s.textContent=WCC_STYLES;this.appendChild(s);this._styleAdded=true}const a=w.attributes||{},c=w.state,temp=this.config.temperature_entity?this._value(this.config.temperature_entity):a.temperature??'—',tu=this.config.temperature_entity?this._unit(this.config.temperature_entity):a.temperature_unit||'°',hum=this.config.humidity_entity?this._value(this.config.humidity_entity):a.humidity??'—',press=this.config.pressure_entity?this._value(this.config.pressure_entity):a.pressure??'—',wind=this.config.wind_speed_entity?this._value(this.config.wind_speed_entity):a.wind_speed??'—',wu=this.config.wind_speed_entity?this._unit(this.config.wind_speed_entity):a.wind_speed_unit||'',dir=this.config.wind_direction_entity?this._value(this.config.wind_direction_entity):a.wind_bearing??'—',uv=this.config.uv_entity?this._value(this.config.uv_entity):a.uv_index??'—';const key=`${this.config.weather_entity}|${w.last_updated||''}`;if(key!==this._forecastKey){this._forecastKey=key;this._forecast=await this._getForecast()}const days=(this._forecast||[]).slice(0,this.config.forecast_days),fh=days.map(d=>`<div class="day"><div class="day-name">${this._day(d.datetime)}</div><div class="day-icon">${this._icon(d.condition)}</div><div class="day-temp"><b>${d.temperature??'—'}°</b> <span>${d.templow!=null?d.templow+'°':''}</span></div><div class="day-rain">${d.precipitation_probability!=null?d.precipitation_probability+'%':'—'} rain</div></div>`).join('');const old=this.querySelector('ha-card');if(old)old.remove();const card=document.createElement('ha-card');card.innerHTML=`<div class="shell ${this._bg(c)}"><div class="topbar"><div><div class="eyebrow">WEATHER COMMAND CENTER</div><div class="title">${this.config.name}</div></div><div class="condition-pill">${this._icon(c)} ${this._label(c)}</div></div><div class="hero"><div class="hero-main"><div class="hero-icon">${this._icon(c)}</div><div><div class="temperature">${temp}<span>${tu}</span></div><div class="feels">Feels like ${a.apparent_temperature??'—'}${tu}</div></div></div><div class="location">${this.config.location||a.friendly_name||this.config.name}</div></div><div class="metrics"><div class="metric"><span>Humidity</span><strong>${hum}${hum!=='—'?'%':''}</strong></div><div class="metric"><span>Pressure</span><strong>${press}</strong></div><div class="metric"><span>Wind</span><strong>${wind} ${wu}</strong></div><div class="metric"><span>Direction</span><strong>${dir}</strong></div><div class="metric"><span>UV Index</span><strong>${uv}</strong></div></div><section><div class="section-title">7 DAY FORECAST</div><div class="days">${fh||'<div class="empty">Forecast unavailable</div>'}</div></section><div class="footer">${w.last_updated?`Updated ${this._time(w.last_updated)}`:'Live Home Assistant weather data'}</div></div>`;this.appendChild(card)}}
if(!customElements.get('weather-command-center'))customElements.define('weather-command-center',WeatherCommandCenter);window.customCards=window.customCards||[];if(!window.customCards.some(c=>c.type==='weather-command-center'))window.customCards.push({type:'weather-command-center',name:'Weather Command Center',description:'Full-screen weather command center for Home Assistant',preview:true,getEntitySuggestion:(h,e)=>e?.startsWith('weather.')?{config:{type:'custom:weather-command-center',weather_entity:e}}:null});
